'use client';

import * as React from 'react';
import { cn } from '@/lib/utils';
import { cva, type VariantProps } from 'class-variance-authority';
import { motion, HTMLMotionProps } from 'framer-motion';
import { AlertCircle, Loader2 } from 'lucide-react';
import type { TimelineColor } from '@/types';

const timelineVariants = cva('flex flex-col relative', {
  variants: {
    size: {
      sm: 'gap-4',
      md: 'gap-6',
      lg: 'gap-8',
    },
  },
  defaultVariants: {
    size: 'md',
  },
});

/**
 * Timeline component props interface
 * @interface TimelineProps
 * @extends {React.HTMLAttributes<HTMLOListElement>}
 * @extends {VariantProps<typeof timelineVariants>}
 */
interface TimelineProps
  extends React.HTMLAttributes<HTMLOListElement>,
    VariantProps<typeof timelineVariants> {
  /** Size of the timeline icons */
  iconsize?: 'sm' | 'md' | 'lg';
}

/**
 * Timeline component for displaying a vertical list of events or items
 * @component
 */
const Timeline = React.forwardRef<HTMLOListElement, TimelineProps>(
  ({ className, iconsize, size, children, ...props }, ref) => {
    const items = React.Children.toArray(children);

    if (items.length === 0) {
      return <TimelineEmpty />;
    }

    return (
      <ol
        ref={ref}
        aria-label="Timeline"
        className={cn(
          timelineVariants({ size }),
          'relative min-h-[600px] w-full max-w-2xl mx-auto py-8',
          className
        )}
        {...props}
      >
        {React.Children.map(children, (child, index) => {
          if (
            React.isValidElement(child) &&
            typeof child.type !== 'string' &&
            'displayName' in child.type &&
            child.type.displayName === 'TimelineItem'
          ) {
            return React.cloneElement(child, {
              iconsize,
              showConnector: index !== items.length - 1,
            } as React.ComponentProps<typeof TimelineItem>);
          }
          return child;
        })}
      </ol>
    );
  },
);
Timeline.displayName = 'Timeline';

/**
 * TimelineItem component props interface
 * @interface TimelineItemProps
 * @extends {Omit<HTMLMotionProps<"li">, "ref">}
 */
interface TimelineItemProps extends Omit<HTMLMotionProps<'li'>, 'ref'> {
  /** Date string for the timeline item */
  date?: string;
  /** Title of the timeline item */
  title?: string;
  /** Description text */
  description?: string;
  /** Custom icon element */
  icon?: React.ReactNode;
  /** Color theme for the icon */
  iconColor?: TimelineColor;
  /** Current status of the item */
  status?: 'completed' | 'in-progress' | 'pending';
  /** Color theme for the connector line */
  connectorColor?: TimelineColor;
  /** Whether to show the connector line */
  showConnector?: boolean;
  /** Size of the icon */
  iconsize?: 'sm' | 'md' | 'lg';
  /** Loading state */
  loading?: boolean;
  /** Error message */
  error?: string;
}

const TimelineItem = React.forwardRef<HTMLLIElement, TimelineItemProps>(
  (
    {
      className,
      date,
      title,
      description,
      icon,
      iconColor,
      status = 'completed',
      connectorColor,
      showConnector = true,
      iconsize,
      loading,
      error,
      // Omit unused Framer Motion props
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      initial,
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      animate,
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      transition,
      ...props
    },
    ref,
  ) => {
    const commonClassName = cn(
      'relative w-full mb-8 last:mb-0',
      className,
    );

    // Loading State
    if (loading) {
      return (
        <motion.li
          ref={ref}
          className={commonClassName}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          role="status"
          {...props}
        >
          <div className="grid grid-cols-[minmax(auto,8rem)_auto_1fr] items-start px-4">
            <div className="pr-4 text-right">
              <div className="h-4 w-24 animate-pulse rounded bg-muted" />
            </div>

            <div className="mx-3 flex flex-col items-center justify-start gap-y-2">
              <div className="relative flex h-8 w-8 animate-pulse items-center justify-center rounded-full bg-muted ring-8 ring-background">
                <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
              </div>
              {showConnector && <div className="h-full w-0.5 animate-pulse bg-muted" />}
            </div>

            <div className="flex flex-col gap-2 pl-2">
              <div className="space-y-2">
                <div className="h-4 w-24 animate-pulse rounded bg-muted" />
                <div className="h-3 w-48 animate-pulse rounded bg-muted" />
              </div>
            </div>
          </div>
        </motion.li>
      );
    }

    // Error State
    if (error) {
      return (
        <motion.li
          ref={ref}
          className={cn(commonClassName, 'border border-destructive/50 bg-destructive/10')}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          role="alert"
          {...props}
        >
          <div className="grid grid-cols-[minmax(auto,8rem)_auto_1fr] items-start px-4">
            <div className="pr-4 text-right">
              <TimelineTime className="text-destructive">{date}</TimelineTime>
            </div>

            <div className="mx-3 flex flex-col items-center justify-start gap-y-2">
              <div className="relative flex h-8 w-8 items-center justify-center rounded-full bg-destructive/20 ring-8 ring-background">
                <AlertCircle className="h-4 w-4 text-destructive" />
              </div>
              {showConnector && <TimelineConnector status="pending" className="h-full" />}
            </div>

            <div className="flex flex-col gap-2 pl-2">
              <TimelineHeader>
                <TimelineTitle className="text-destructive">{title || 'Error'}</TimelineTitle>
              </TimelineHeader>
              <TimelineDescription className="text-destructive">{error}</TimelineDescription>
            </div>
          </div>
        </motion.li>
      );
    }

    const content = (
      <div
        className="grid grid-cols-[1fr_auto_1fr] gap-4 items-start"
        {...(status === 'in-progress' ? { 'aria-current': 'step' } : {})}
      >
        {/* Date */}
        <div className="flex flex-col justify-start pt-1">
          <TimelineTime className="text-right pr-4">{date}</TimelineTime>
        </div>

        {/* Timeline dot and connector */}
        <div className="flex flex-col items-center">
          <div className="relative z-10">
            <TimelineIcon icon={icon} color={iconColor} status={status} iconSize={iconsize} />
          </div>
          {showConnector && (
            <div className="h-16 w-0.5 bg-border mt-2" />
          )}
        </div>

        {/* Content */}
        <TimelineContent>
          <TimelineHeader>
            <TimelineTitle>{title}</TimelineTitle>
          </TimelineHeader>
          <TimelineDescription>{description}</TimelineDescription>
        </TimelineContent>
      </div>
    );

    // Filter out Framer Motion specific props
    const {
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      style,
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      onDrag,
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      onDragStart,
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      onDragEnd,
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      onAnimationStart,
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      onAnimationComplete,
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      transformTemplate,
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      whileHover,
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      whileTap,
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      whileDrag,
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      whileFocus,
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      whileInView,
      ...filteredProps
    } = props;

    return (
      <li ref={ref} className={commonClassName} {...filteredProps}>
        {content}
      </li>
    );
  },
);
TimelineItem.displayName = 'TimelineItem';

interface TimelineTimeProps extends React.HTMLAttributes<HTMLTimeElement> {
  /** Date string, Date object, or timestamp */
  date?: string | Date | number;
  /** Optional format for displaying the date */
  format?: Intl.DateTimeFormatOptions;
}

const defaultDateFormat: Intl.DateTimeFormatOptions = {
  year: 'numeric',
  month: 'short',
  day: '2-digit',
};

const TimelineTime = React.forwardRef<HTMLTimeElement, TimelineTimeProps>(
  ({ className, date, format, children, ...props }, ref) => {
    const formattedDate = React.useMemo(() => {
      if (!date) return '';

      try {
        const dateObj = new Date(date);
        if (isNaN(dateObj.getTime())) return '';

        return new Intl.DateTimeFormat('en-US', {
          ...defaultDateFormat,
          ...format,
        }).format(dateObj);
      } catch (error) {
        console.error('Error formatting date:', error);
        return '';
      }
    }, [date, format]);

    return (
      <time
        ref={ref}
        dateTime={date ? new Date(date).toISOString() : undefined}
        className={cn('text-sm font-medium tracking-tight text-muted-foreground', className)}
        {...props}
      >
        {children || formattedDate}
      </time>
    );
  },
);
TimelineTime.displayName = 'TimelineTime';

const TimelineConnector = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement> & {
    status?: 'completed' | 'in-progress' | 'pending';
    color?: 'primary' | 'secondary' | 'muted' | 'accent';
  }
>(({ className, status = 'completed', color, ...props }, ref) => (
  <div
    ref={ref}
    className={cn(
      'w-0.5',
      {
        'bg-primary': color === 'primary' || (!color && status === 'completed'),
        'bg-muted': color === 'muted' || (!color && status === 'pending'),
        'bg-secondary': color === 'secondary',
        'bg-accent': color === 'accent',
        'bg-gradient-to-b from-primary to-muted': !color && status === 'in-progress',
      },
      className,
    )}
    {...props}
  />
));
TimelineConnector.displayName = 'TimelineConnector';

const TimelineHeader = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, ...props }, ref) => (
    <div ref={ref} className={cn('flex items-center gap-4', className)} {...props} />
  ),
);
TimelineHeader.displayName = 'TimelineHeader';

const TimelineTitle = React.forwardRef<
  HTMLHeadingElement,
  React.HTMLAttributes<HTMLHeadingElement>
>(({ className, children, ...props }, ref) => (
  <h3
    ref={ref}
    className={cn('font-semibold leading-none tracking-tight text-secondary-foreground', className)}
    {...props}
  >
    {children}
  </h3>
));
TimelineTitle.displayName = 'TimelineTitle';

const TimelineIcon = ({
  icon,
  color = 'primary',
  status = 'completed',
  iconSize = 'md',
}: {
  icon?: React.ReactNode;
  color?: 'primary' | 'secondary' | 'muted' | 'accent' | 'destructive';
  status?: 'completed' | 'in-progress' | 'pending' | 'error';
  iconSize?: 'sm' | 'md' | 'lg';
}) => {
  const sizeClasses = {
    sm: 'h-8 w-8',
    md: 'h-10 w-10',
    lg: 'h-12 w-12',
  };

  const iconSizeClasses = {
    sm: 'h-4 w-4',
    md: 'h-5 w-5',
    lg: 'h-6 w-6',
  };

  const colorClasses = {
    primary: 'bg-primary text-primary-foreground',
    secondary: 'bg-secondary text-secondary-foreground',
    muted: 'bg-muted text-muted-foreground',
    accent: 'bg-accent text-accent-foreground',
    destructive: 'bg-destructive text-destructive-foreground',
  };

  return (
    <div
      className={cn(
        'relative flex items-center justify-center rounded-full ring-8 ring-background shadow-sm',
        sizeClasses[iconSize],
        colorClasses[color],
      )}
    >
      {icon ? (
        <div className={cn('flex items-center justify-center', iconSizeClasses[iconSize])}>
          {icon}
        </div>
      ) : (
        <div className={cn('rounded-full', iconSizeClasses[iconSize])} />
      )}
    </div>
  );
};

const TimelineDescription = React.forwardRef<
  HTMLParagraphElement,
  React.HTMLAttributes<HTMLParagraphElement>
>(({ className, ...props }, ref) => (
  <p ref={ref} className={cn('max-w-sm text-sm text-muted-foreground', className)} {...props} />
));
TimelineDescription.displayName = 'TimelineDescription';

const TimelineContent = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, ...props }, ref) => (
    <div ref={ref} className={cn('flex flex-col gap-2 pl-2', className)} {...props} />
  ),
);
TimelineContent.displayName = 'TimelineContent';

const TimelineEmpty = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, children, ...props }, ref) => (
    <div
      ref={ref}
      className={cn('flex flex-col items-center justify-center p-8 text-center', className)}
      {...props}
    >
      <p className="text-sm text-muted-foreground">{children || 'No timeline items to display'}</p>
    </div>
  ),
);
TimelineEmpty.displayName = 'TimelineEmpty';

export {
  Timeline,
  TimelineItem,
  TimelineConnector,
  TimelineHeader,
  TimelineTitle,
  TimelineIcon,
  TimelineDescription,
  TimelineContent,
  TimelineTime,
  TimelineEmpty,
};

import type { Meta, StoryObj } from '@storybook/react';
import { expect, within } from '@storybook/test';

import { TimelineLayout } from './timeline-layout';
import {
  defaultItems,
  stateItems,
  sizedItems,
  loadingItems,
  errorItems,
  timelineFixtures,
} from './__fixtures__/timeline-items';

const meta = {
  title: 'Components/Timeline',
  component: TimelineLayout,
  parameters: {
    layout: 'centered',
    docs: {
      description: {
        component:
          'A beautiful, accessible timeline component that supports various states, sizes, and customizations.',
      },
    },
  },
  tags: ['autodocs'],
  argTypes: {
    size: {
      description: 'The size of the timeline component',
      control: 'select',
      options: ['sm', 'md', 'lg'],
      defaultValue: 'md',
      table: {
        type: { summary: 'string' },
      },
    },
    iconColor: {
      description: 'The color of the timeline icons',
      control: 'select',
      options: ['primary', 'secondary', 'muted', 'accent'],
      defaultValue: 'primary',
      table: {
        type: { summary: 'string' },
      },
    },
    connectorColor: {
      description: 'The color of the connector lines',
      control: 'select',
      options: ['primary', 'secondary', 'muted', 'accent'],
      defaultValue: 'primary',
      table: {
        type: { summary: 'string' },
      },
    },
    animate: {
      description: 'Whether to animate the timeline items',
      control: 'boolean',
      defaultValue: true,
      table: {
        type: { summary: 'boolean' },
      },
    },
    items: {
      description: 'Array of timeline items',
      control: 'object',
      table: {
        type: { summary: 'TimelineElement[]' },
      },
    },
    className: {
      description: 'Additional CSS classes',
      control: 'text',
      table: {
        type: { summary: 'string' },
      },
    },
  },
} satisfies Meta<typeof TimelineLayout>;

export default meta;
type Story = StoryObj<typeof meta>;

const commonClasses = 'min-h-[600px] w-full max-w-2xl mx-auto p-8 flex items-center justify-center';

export const Default: Story = {
  args: {
    items: defaultItems.map(item => ({ ...item, color: undefined })),
    size: 'md',
    animate: true,
    iconColor: 'primary',
    connectorColor: 'primary',
    className: commonClasses,
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    // Check if all timeline items are rendered
    const items = await canvas.findAllByRole('listitem');
    expect(items).toHaveLength(defaultItems.length);

    // Check if titles are rendered correctly
    defaultItems.forEach(async (item) => {
      expect(await canvas.findByText(item.title)).toBeInTheDocument();
    });

    // Check if dates are rendered
    defaultItems.forEach(async (item) => {
      expect(await canvas.findByText(item.date)).toBeInTheDocument();
    });

    // Check if descriptions are rendered
    defaultItems.forEach(async (item) => {
      expect(await canvas.findByText(item.description)).toBeInTheDocument();
    });
  },
};

export const CustomColors: Story = {
  args: {
    items: defaultItems.map((item) => ({ ...item, color: undefined })),
    size: 'md',
    animate: true,
    iconColor: 'accent',
    connectorColor: 'accent',
    className: commonClasses,
  },
  play: async ({ canvasElement, args }) => {
    const canvas = within(canvasElement);

    // Increase wait time to ensure elements are rendered
    await new Promise((resolve) => setTimeout(resolve, 500));

    // Check if items are rendered
    const items = canvas.getAllByRole('listitem');
    expect(items).toHaveLength(defaultItems.length);

    // Check for any timeline item with accent color
    const timelineItems = canvasElement.querySelectorAll('li');
    let hasAccentColor = false;

    timelineItems.forEach((item) => {
      if (
        item.querySelector('[class*="text-accent"]') ||
        item.querySelector('[class*="after:bg-accent"]')
      ) {
        hasAccentColor = true;
      }
    });

    expect(hasAccentColor).toBeTruthy();
  },
};

export const States: Story = {
  args: {
    items: stateItems,
    animate: true,
    iconColor: 'primary',
    connectorColor: 'primary',
    className: commonClasses,
  },
};

export const Small: Story = {
  args: {
    items: sizedItems.sm,
    size: 'sm',
    animate: true,
    className: commonClasses,
  },
};

export const Loading: Story = {
  args: {
    items: loadingItems,
    animate: false,
    className: commonClasses,
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    // Wait for loading elements to render
    await new Promise((resolve) => setTimeout(resolve, 500));

    // Check for loading skeletons
    const loadingItems = canvas.getAllByRole('listitem');
    expect(loadingItems.length).toBeGreaterThan(0);

    // Check for loading state indicators
    const loadingTexts = canvas.getAllByText('Loading...');
    expect(loadingTexts.length).toBeGreaterThan(0);

    // Check for "Content is loading..." text
    const loadingDescriptions = canvas.getAllByText('Content is loading...');
    expect(loadingDescriptions.length).toBeGreaterThan(0);
  },
};

export const Error: Story = {
  args: {
    items: errorItems,
    animate: false,
    className: commonClasses,
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    // Wait for elements to render
    await new Promise((resolve) => setTimeout(resolve, 500));

    // Check if error items are rendered
    const items = canvas.getAllByRole('listitem');
    expect(items.length).toBeGreaterThan(0);

    // Check for error styling
    const errorIcon = canvasElement.querySelector('[class*="bg-destructive"]');
    expect(errorIcon).toBeTruthy();

    // Check for error content
    const errorTitle = canvas.getByText('Error State');
    expect(errorTitle).toBeInTheDocument();

    const errorDescription = canvas.getByText('An error occurred while loading this item.');
    expect(errorDescription).toBeInTheDocument();

    const warningIcon = canvasElement.querySelector('[data-testid="warning-icon"]');
    expect(warningIcon).toBeTruthy();
  },
};

export const CustomGenerated: Story = {
  args: {
    items: timelineFixtures.createCustom(5, { color: 'accent' }),
    animate: true,
    className: commonClasses,
  },
};

export const EdgeCases: Story = {
  args: {
    items: [
      // Test empty case
      {
        id: 1,
        date: '',
        title: '',
        description: '',
      },
      // Test minimal case
      {
        id: 2,
        date: '',
        title: '',
        description: '',
        size: 'sm',
      },
      // Test all color variants
      {
        id: 3,
        date: '2024-01-01',
        title: 'Primary Color',
        description: 'Testing primary color',
        color: 'primary',
      },
      {
        id: 4,
        date: '2024-01-02',
        title: 'Secondary Color',
        description: 'Testing secondary color',
        color: 'secondary',
      },
      {
        id: 5,
        date: '2024-01-03',
        title: 'Accent Color',
        description: 'Testing accent color',
        color: 'accent',
      },
      // Test all status variants
      {
        id: 6,
        date: '2024-01-04',
        title: 'Completed Status',
        description: 'Testing completed status',
        status: 'completed',
      },
      {
        id: 7,
        date: '2024-01-05',
        title: 'In Progress Status',
        description: 'Testing in-progress status',
        status: 'in-progress',
      },
      {
        id: 8,
        date: '2024-01-06',
        title: 'Pending Status',
        description: 'Testing pending status',
        status: 'pending',
      },
    ],
    animate: false,
    className: commonClasses,
  },
};

// Add test for custom connector colors
export const CustomConnectors: Story = {
  args: {
    items: [
      {
        id: 1,
        date: '2024-01-01',
        title: 'Custom Connector',
        description: 'Item with custom connector',
        color: 'accent',
      },
      {
        id: 2,
        date: '2024-01-02',
        title: 'No Connector',
        description: 'Item without connector',
      },
      {
        id: 3,
        date: '2024-01-03',
        title: 'Last Item',
        description: 'Final item in timeline',
      },
    ],
    connectorColor: 'accent',
    className: commonClasses,
  },
};

// Add test for custom icons
export const CustomIcons: Story = {
  args: {
    items: [
      {
        id: 1,
        date: '2024-01-01',
        title: 'Custom Icon',
        description: 'Item with custom icon',
        icon: <span data-testid="custom-icon">★</span>,
      },
    ],
    className: commonClasses,
  },
};
